@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --font-body: var(--font-inter);
    --font-headline: var(--font-inter);
    --background: 220 13% 98%; /* slate-50 #f8fafc */
    --foreground: 222.2 84% 4.9%;

    --card: 0 0% 100%;
    --card-foreground: 222.2 84% 4.9%;

    --popover: 0 0% 100%;
    --popover-foreground: 222.2 84% 4.9%;

    --primary: 221 83% 53%; /* blue-600 #2563eb */
    --primary-foreground: 210 40% 98%;

    --secondary: 210 40% 96.1%; /* slate-100 */
    --secondary-foreground: 222.2 47.4% 11.2%; /* slate-900 */

    --muted: 210 40% 96.1%; /* slate-100 */
    --muted-foreground: 215.4 16.3% 46.9%; /* slate-500 #64748B */

    --accent: 210 40% 96.1%; /* slate-100 */
    --accent-foreground: 222.2 47.4% 11.2%;

    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 210 40% 98%;

    --success: 161 51% 59%;

    --border: 214.3 31.8% 91.4%; /* slate-200 */
    --input: 214.3 31.8% 91.4%;
    --ring: 221.2 83.2% 53.3%;

    --radius: 1rem;

    --app-shell-bg: #0f1e33;
    --app-shell-bg-gradient: linear-gradient(180deg, #0f1e33 0%, #0f1e33 100%);
    --app-topbar-bg: rgba(15, 30, 51, 0.96);
    --app-sidebar-bg: #0f1e33;
    --app-footer-bg: #0f1e33;
    --app-sidebar-border: rgba(255, 255, 255, 0.1);
    --app-sidebar-thumb: #3d5d82;
    --app-sidebar-thumb-hover: #4a719d;
    --app-sidebar-active-bg: linear-gradient(90deg, #13b180 0%, #37e6a5 100%);
    --app-sidebar-active-foreground: #051f20;
    --app-surface-solid: #152a47;
    --app-surface-elevated: linear-gradient(180deg, rgba(21, 42, 71, 0.98) 0%, rgba(10, 22, 39, 1) 100%);
    --app-surface-soft: rgba(255, 255, 255, 0.04);
    --app-surface-input: #162538;
    --app-surface-border: rgba(255, 255, 255, 0.12);
    --app-highlight: #22c55e;
    --app-highlight-soft: #86efac;
    --app-highlight-glow: rgba(34, 197, 94, 0.18);
    --app-nav-foreground: #ffffff;
    --app-nav-muted: rgba(255, 255, 255, 0.7);
    --app-nav-hover-bg: rgba(255, 255, 255, 0.1);
    --app-nav-hover-foreground: #ffffff;
    --app-page-foreground: #ffffff;
    --app-page-muted: rgba(255, 255, 255, 0.68);
    --app-page-background: hsl(var(--background));
    --app-muted-foreground: var(--app-page-muted);
    --app-surface: hsl(var(--card));
    --app-nav-active-bg: hsl(var(--primary));
    --app-nav-active-foreground: hsl(var(--primary-foreground));
    --public-shell-bg: radial-gradient(circle at top, rgba(212, 175, 55, 0.12), transparent 24%), linear-gradient(180deg, #050505 0%, #0b0b0d 42%, #121214 100%);
    --public-header-bg: rgba(16, 17, 19, 0.95);
    --public-footer-bg: linear-gradient(180deg, rgba(6, 8, 8, 0.96) 0%, rgba(9, 12, 11, 0.98) 100%);
    --public-card-bg: radial-gradient(circle at top left, rgba(74, 222, 128, 0.2), transparent 28%), linear-gradient(135deg, rgba(7, 18, 12, 0.96) 0%, rgba(10, 10, 12, 0.98) 52%, rgba(16, 24, 18, 0.96) 100%);
    --public-card-bg-soft: radial-gradient(circle at top left, rgba(74, 222, 128, 0.12), transparent 28%), linear-gradient(145deg, rgba(10, 18, 14, 0.98) 0%, rgba(8, 10, 10, 0.99) 52%, rgba(12, 22, 16, 0.98) 100%);
    --public-card-border: rgba(74, 222, 128, 0.2);
    --public-accent: #4ade80;
    --public-accent-soft: #86efac;
    --public-accent-strong: #166534;
    --public-muted: rgba(255, 255, 255, 0.74);
  }

  .dark {
    --background: 222.2 84% 4.9%;
    --foreground: 210 40% 98%;
    --card: 222.2 84% 4.9%;
    --card-foreground: 210 40% 98%;
    --popover: 222.2 84% 4.9%;
    --popover-foreground: 210 40% 98%;
    --primary: 217.1 91.2% 59.8%;
    --primary-foreground: 222.2 47.4% 11.2%;
    --secondary: 217.2 32.6% 17.5%;
    --secondary-foreground: 210 40% 98%;
    --muted: 217.2 32.6% 17.5%;
    --muted-foreground: 215 20.2% 65.1%;
    --accent: 217.2 32.6% 17.5%;
    --accent-foreground: 210 40% 98%;
    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 210 40% 98%;
    --border: 217.2 32.6% 17.5%;
    --input: 217.2 32.6% 17.5%;
    --ring: 217.1 91.2% 59.8%;
    --radius: 1rem;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
    font-family: var(--font-body);
    font-feature-settings: "cv02", "cv03", "cv04", "cv11";
  }
}

@layer utilities {
  @keyframes agentfinder-appearance-pulse {
    0% {
      box-shadow: 0 0 0 0 hsl(var(--primary) / 0.28);
    }
    100% {
      box-shadow: 0 0 0 20px hsl(var(--primary) / 0);
    }
  }

  @keyframes background-pan {
    from {
      background-position: 0% center;
    }
    to {
      background-position: -200% center;
    }
  }
  .animated-glow {
    background-image: radial-gradient(
      ellipse 80% 50% at 50% 120%,
      hsl(var(--primary) / 0.15),
      transparent
    );
    animation: background-pan 10s linear infinite;
    background-size: 200% 100%;
  }
  .glow-card {
    box-shadow: 0 0 40px rgba(5, 255, 255, 0.3);
    border-color: rgba(5, 255, 255, 0.4);
  }
  .button-glow {
    box-shadow: 0 0 12px hsl(var(--primary) / 0.6);
  }

  .agentfinder-appearance-dialog {
    overflow: hidden;
    border: 1px solid hsl(var(--border));
    background:
      radial-gradient(circle at 100% 0%, hsl(var(--primary) / 0.08), transparent 34%),
      hsl(var(--background));
    color: hsl(var(--foreground));
    box-shadow: 0 28px 72px rgba(15, 23, 42, 0.28);
  }

  .agentfinder-appearance-dialog > button.absolute {
    top: 0.85rem;
    right: 0.85rem;
    height: 2.5rem;
    width: 2.5rem;
    border: 1px solid hsl(var(--border));
    border-radius: 999px;
    background: hsl(var(--background) / 0.88);
    color: hsl(var(--muted-foreground));
    box-shadow: 0 10px 24px rgba(15, 23, 42, 0.14);
  }

  .agentfinder-appearance-dialog__header {
    padding: 1.55rem 1.35rem 0.75rem;
    text-align: left;
  }

  .agentfinder-appearance-dialog__badge {
    display: inline-flex;
    width: fit-content;
    align-items: center;
    gap: 0.45rem;
    border: 1px solid hsl(var(--primary) / 0.22);
    border-radius: 999px;
    background: hsl(var(--primary) / 0.08);
    padding: 0.35rem 0.7rem;
    color: hsl(var(--primary));
    font-size: 0.72rem;
    font-weight: 800;
  }

  .agentfinder-appearance-dialog__badge svg {
    color: currentColor;
    stroke: currentColor;
  }

  .agentfinder-appearance-dialog__title {
    margin-top: 0.9rem;
    color: hsl(var(--foreground));
    font-size: 1.45rem;
    letter-spacing: 0;
  }

  .agentfinder-appearance-dialog__description {
    max-width: 22rem;
    color: hsl(var(--muted-foreground));
    font-size: 0.92rem;
    line-height: 1.55;
  }

  .agentfinder-appearance-dialog__options {
    display: grid;
    gap: 0.78rem;
    padding: 0.35rem 1.1rem 1.15rem;
  }

  .agentfinder-appearance-dialog__option {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 0.9rem;
    align-items: center;
    width: 100%;
    border: 1px solid hsl(var(--border));
    border-radius: 1.25rem;
    background: hsl(var(--card) / 0.92);
    padding: 0.82rem;
    text-align: left;
    color: hsl(var(--foreground));
    box-shadow:
      0 12px 28px rgba(15, 23, 42, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.7);
    transition:
      transform 180ms ease,
      border-color 180ms ease,
      box-shadow 180ms ease;
  }

  .agentfinder-appearance-dialog__option:hover,
  .agentfinder-appearance-dialog__option:focus-visible {
    border-color: hsl(var(--primary) / 0.34);
    box-shadow:
      0 18px 38px rgba(15, 23, 42, 0.12),
      inset 0 1px 0 rgba(255, 255, 255, 0.88);
    transform: translateY(-2px);
  }

  .agentfinder-appearance-dialog__option--active {
    border-color: hsl(var(--primary) / 0.42);
    background: hsl(var(--primary) / 0.08);
  }

  .agentfinder-appearance-dialog__swatch {
    display: inline-flex;
    height: 2.55rem;
    width: 2.55rem;
    border: 1.5px solid hsl(var(--border));
    border-radius: 999px;
    box-shadow:
      0 12px 24px rgba(15, 23, 42, 0.12),
      inset 0 1px 0 rgba(255, 255, 255, 0.74);
  }

  .agentfinder-appearance-dialog__copy {
    display: grid;
    min-width: 0;
    gap: 0.18rem;
  }

  .agentfinder-appearance-dialog__name {
    color: hsl(var(--foreground));
    font-size: 0.98rem;
    font-weight: 850;
  }

  .agentfinder-appearance-dialog__accent {
    color: hsl(var(--primary));
    font-size: 0.74rem;
    font-weight: 800;
    text-transform: uppercase;
  }

  .agentfinder-appearance-dialog__check {
    display: inline-flex;
    height: 2rem;
    width: 2rem;
    align-items: center;
    justify-content: center;
    border: 1px solid hsl(var(--primary) / 0.34);
    border-radius: 999px;
    background: hsl(var(--primary) / 0.1);
    color: hsl(var(--primary));
  }

  .agentfinder-appearance-dialog__check svg {
    color: currentColor;
    stroke: currentColor;
  }

  .agentfinder-appearance-pulse-launcher {
    min-height: 4rem;
  }

  .agentfinder-appearance-pulse-launcher__pulse {
    position: relative;
    display: inline-flex;
    height: 2.25rem;
    width: 2.25rem;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .agentfinder-appearance-pulse-launcher__pulse::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 999px;
    animation: agentfinder-appearance-pulse 2s infinite;
    background: transparent;
    box-shadow: 0 0 0 0 hsl(var(--primary) / 0.28);
  }

  .agentfinder-appearance-pulse-launcher__dot {
    display: inline-flex;
    height: 1rem;
    width: 1rem;
    border-radius: 999px;
    background: hsl(var(--primary));
    box-shadow:
      0 0 0 1px hsl(var(--background) / 0.35),
      0 8px 20px hsl(var(--primary) / 0.32);
  }

  .agentfinder-appearance-pulse-launcher__copy {
    display: grid;
    min-width: 0;
    gap: 0.1rem;
  }

  .agentfinder-appearance-pulse-launcher__label {
    color: hsl(var(--foreground));
    font-size: 0.96rem;
    font-weight: 700;
    line-height: 1.1;
  }

  .agentfinder-appearance-pulse-launcher__subtle {
    color: hsl(var(--muted-foreground));
    font-size: 0.74rem;
    line-height: 1.1;
  }

  @keyframes demo-conversion-orbit {
    0% {
      transform: scale(0.94);
      opacity: 0.42;
    }
    70% {
      transform: scale(1.24);
      opacity: 0;
    }
    100% {
      transform: scale(1.24);
      opacity: 0;
    }
  }

  @keyframes demo-conversion-float {
    0%,
    100% {
      transform: translate3d(0, 0, 0);
    }
    50% {
      transform: translate3d(0, -6px, 0);
    }
  }

  .demo-conversion-modal {
    overflow: hidden;
    border: 1px solid rgba(112, 144, 193, 0.24);
    background:
      radial-gradient(circle at 18% 14%, rgba(88, 138, 255, 0.32), transparent 28%),
      radial-gradient(circle at 82% 18%, rgba(45, 212, 191, 0.16), transparent 22%),
      linear-gradient(145deg, rgba(8, 18, 34, 0.98), rgba(11, 24, 45, 0.985) 48%, rgba(7, 14, 28, 0.99));
    box-shadow:
      0 42px 120px rgba(2, 8, 24, 0.52),
      inset 0 1px 0 rgba(255, 255, 255, 0.06);
    backdrop-filter: blur(18px);
  }

  .demo-conversion-modal::before {
    content: '';
    position: absolute;
    inset: 1px;
    border-radius: inherit;
    background:
      linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0)),
      radial-gradient(circle at top, rgba(129, 161, 255, 0.12), transparent 34%);
    pointer-events: none;
  }

  .demo-conversion-modal::after {
    content: '';
    position: absolute;
    inset: auto -12% -22% auto;
    width: 18rem;
    height: 18rem;
    border-radius: 999px;
    background: radial-gradient(circle, rgba(53, 208, 180, 0.2), rgba(53, 208, 180, 0));
    filter: blur(24px);
    pointer-events: none;
  }

  .demo-conversion-modal__close {
    position: absolute;
    top: 1rem;
    right: 1rem;
    z-index: 2;
    display: inline-flex;
    height: 2.75rem;
    width: 2.75rem;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.06);
    color: rgba(232, 240, 255, 0.78);
    box-shadow: 0 16px 36px rgba(2, 8, 24, 0.22);
    backdrop-filter: blur(10px);
    transition:
      background 180ms ease,
      transform 180ms ease,
      color 180ms ease;
  }

  .demo-conversion-modal__close:hover {
    background: rgba(255, 255, 255, 0.12);
    color: #ffffff;
    transform: translateY(-1px);
  }

  .demo-conversion-modal__badge-row {
    display: flex;
    flex-wrap: wrap;
    gap: 0.7rem;
    justify-content: center;
    padding-left: 3.25rem;
    padding-right: 3.25rem;
  }

  .demo-conversion-modal__content {
    margin-left: auto;
    margin-right: auto;
    max-width: 56rem;
    align-items: center;
  }

  .demo-conversion-modal__badge {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.06);
    padding: 0.55rem 0.9rem;
    color: rgba(236, 243, 255, 0.9);
    font-size: 0.7rem;
    font-weight: 800;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    backdrop-filter: blur(10px);
  }

  .demo-conversion-modal__eyebrow {
    display: block;
    width: 100%;
    color: rgba(178, 195, 223, 0.72);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.2em;
    text-align: center;
    text-transform: uppercase;
  }

  .demo-conversion-modal__title {
    display: block;
    width: 100%;
    max-width: 49rem;
    margin-left: auto;
    margin-right: auto;
    color: #f8fbff !important;
    font-size: clamp(2.05rem, 3.7vw, 3.95rem);
    font-weight: 900;
    line-height: 1.02;
    letter-spacing: -0.06em;
    text-align: center;
    text-wrap: balance;
  }

  .demo-conversion-modal__title-inline {
    white-space: nowrap;
  }

  .demo-conversion-modal__title-accent {
    background: linear-gradient(90deg, #ffffff 0%, #9fdcff 45%, #9af0d4 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .demo-conversion-modal__description {
    max-width: 36rem;
    margin-left: auto;
    margin-right: auto;
    color: rgba(210, 222, 244, 0.78) !important;
    font-size: 1rem;
    line-height: 1.85;
    text-align: center;
  }

  .demo-conversion-modal__primary-button {
    height: 3.25rem;
    width: 100%;
    border: 0;
    border-radius: 999px;
    background: linear-gradient(135deg, #edf6ff, #ffffff);
    color: #06111f;
    box-shadow:
      0 18px 42px rgba(126, 201, 255, 0.18),
      inset 0 1px 0 rgba(255, 255, 255, 0.82);
    font-weight: 700;
    position: relative;
    overflow: visible;
  }

  .demo-conversion-modal__primary-button:hover {
    background: linear-gradient(135deg, #ffffff, #f4f9ff) !important;
    color: #06111f !important;
  }

  .demo-conversion-modal__primary-button::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    box-shadow: 0 0 0 0 rgba(173, 223, 255, 0.34);
    animation: agentfinder-appearance-pulse 2s infinite;
    pointer-events: none;
  }

  .demo-conversion-modal__secondary-button {
    height: 3.25rem;
    width: 100%;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.06);
    color: rgba(238, 244, 255, 0.92);
    backdrop-filter: blur(10px);
  }

  .demo-conversion-modal__secondary-button:hover {
    background: rgba(255, 255, 255, 0.1) !important;
    color: #ffffff !important;
  }

  .demo-conversion-modal__footer-shell {
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    background:
      linear-gradient(180deg, rgba(8, 18, 34, 0.18), rgba(8, 18, 34, 0.74));
    padding: 1rem 1.25rem 1.15rem;
    box-shadow: 0 -18px 42px rgba(2, 8, 24, 0.22);
    backdrop-filter: blur(16px);
  }

  @media (min-width: 640px) {
    .demo-conversion-modal__footer-shell {
      padding: 1.15rem 1.75rem 1.35rem;
    }

    .demo-conversion-modal__primary-button,
    .demo-conversion-modal__secondary-button {
      width: auto;
      min-width: 240px;
    }
  }

  @media (max-width: 640px) {
    .demo-conversion-modal__title-inline {
      white-space: normal;
    }
  }

  [data-app-theme='agentfinder'] .agentfinder-surface {
    background: var(--app-surface-elevated) !important;
    border-color: var(--app-surface-border) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-soft {
    background: var(--app-surface-soft) !important;
    border-color: var(--app-surface-border) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-topbar {
    background: var(--app-sidebar-bg) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-input {
    background: var(--app-surface-input) !important;
    border-color: var(--app-surface-border) !important;
    color: hsl(var(--foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-input::placeholder {
    color: hsl(var(--muted-foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form input:not([type='color']),
  [data-app-theme='agentfinder'] .agentfinder-form textarea,
  [data-app-theme='agentfinder'] .agentfinder-form button[role='combobox'] {
    background: var(--app-surface-input) !important;
    border-color: var(--app-surface-border) !important;
    color: hsl(var(--foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form input:not([type='color'])::placeholder,
  [data-app-theme='agentfinder'] .agentfinder-form textarea::placeholder {
    color: hsl(var(--muted-foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form .text-white,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/90,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/80,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/75 {
    color: hsl(var(--foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/72,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/70,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/68,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/65,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/62,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/60,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/55,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/50,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/45,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/40,
  [data-app-theme='agentfinder'] .agentfinder-form .text-white\/35 {
    color: hsl(var(--muted-foreground)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form .bg-white\/10,
  [data-app-theme='agentfinder'] .agentfinder-form .bg-white\/\[0\.06\],
  [data-app-theme='agentfinder'] .agentfinder-form .bg-white\/\[0\.04\],
  [data-app-theme='agentfinder'] .agentfinder-form .bg-white\/\[0\.03\],
  [data-app-theme='agentfinder'] .agentfinder-form .bg-white\/5 {
    background: hsl(var(--secondary)) !important;
  }

  [data-app-theme='agentfinder'] .agentfinder-form .border-white\/10,
  [data-app-theme='agentfinder'] .agentfinder-form .border-white\/14,
  [data-app-theme='agentfinder'] .agentfinder-form .border-white\/15,
  [data-app-theme='agentfinder'] .agentfinder-form .border-white\/20 {
    border-color: hsl(var(--border)) !important;
  }

  [data-app-theme='agentfinder'] {
    color-scheme: light;
  }

  [data-app-theme='agentfinder'] body,
  [data-app-theme='agentfinder'] main,
  [data-app-theme='agentfinder'] .min-h-screen,
  [data-app-theme='agentfinder'] .bg-background {
    background-color: hsl(var(--background)) !important;
    color: hsl(var(--foreground)) !important;
  }

  [data-app-theme='agentfinder'] [class*='bg-[#050806]'],
  [data-app-theme='agentfinder'] [class*='bg-[#07111f]'],
  [data-app-theme='agentfinder'] [class*='bg-[#08111F]'],
  [data-app-theme='agentfinder'] [class*='bg-[#081a2c]'],
  [data-app-theme='agentfinder'] [class*='bg-[#0b0f0d]'],
  [data-app-theme='agentfinder'] [class*='bg-[#0B1728]'],
  [data-app-theme='agentfinder'] [class*='bg-[#0b1727]'],
