@keyframes agentfinder-dashboard-confetti-fall {
  0% {
    transform: translate3d(0, -14px, 0) rotate(0deg);
    opacity: 0;
  }

  12% {
    opacity: 1;
  }

  100% {
    transform: translate3d(var(--agentfinder-confetti-drift, 0px), calc(100% + 220px), 0) rotate(var(--agentfinder-confetti-rotation, 180deg));
    opacity: 0;
  }
}

.agentfinder-dashboard-confetti-layer {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}

.agentfinder-dashboard-confetti-piece {
  position: absolute;
  top: -16px;
  border-radius: 2px;
  animation-name: agentfinder-dashboard-confetti-fall;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.14);
  will-change: transform, opacity;
}

@keyframes landing-orb-drift {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
  }

  50% {
    transform: translate3d(0, -18px, 0) scale(1.05);
  }
}

@keyframes landing-float {
  0%,
  100% {
    transform: translate3d(0, 0, 0);
  }

  50% {
    transform: translate3d(0, -10px, 0);
  }
}

@keyframes landing-pulse-ring {
  0% {
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.34);
  }

  100% {
    box-shadow: 0 0 0 26px rgba(59, 130, 246, 0);
  }
}

@keyframes landing-shimmer {
  from {
    background-position: 0% 50%;
  }

  to {
    background-position: 200% 50%;
  }
}

@keyframes landing-card-breathe {
  0%,
  100% {
    transform: translate3d(0, 0, 0) scale(1);
    box-shadow:
      0 20px 50px rgba(37, 55, 88, 0.08),
      0 0 0 0 rgba(96, 165, 250, 0.1),
      inset 0 1px 0 rgba(255, 255, 255, 0.96);
  }

  50% {
    transform: translate3d(0, -4px, 0) scale(1.015);
    box-shadow:
      0 28px 64px rgba(37, 55, 88, 0.12),
      0 0 0 12px rgba(96, 165, 250, 0),
