  position: relative;
  isolation: isolate;
  counter-increment: lux-module;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgb(var(--module-accent-rgb) / 0.28);
  border-radius: 8px;
  background:
    linear-gradient(118deg, rgb(var(--module-accent-rgb) / 0.24), rgba(15, 23, 42, 0) 33%),
    linear-gradient(160deg, rgba(15, 23, 42, 0.1) 0%, rgba(6, 78, 59, 0.34) 100%),
    linear-gradient(180deg, rgba(30, 41, 59, 0.96), rgba(5, 18, 31, 0.98));
