  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.lux-module:nth-child(2n) {
  --module-accent-rgb: 103 232 249;
  --module-edge-rgb: 94 234 212;
}

.lux-module:nth-child(3n) {
  --module-accent-rgb: 45 212 191;
