  background-size: 44px 44px;
  opacity: 0.42;
  pointer-events: none;
}

.lux-module::after {
  content: "0" counter(lux-module);
  position: absolute;
  right: 4.2rem;
  top: 0.9rem;
  z-index: -1;
  color: rgb(var(--module-accent-rgb) / 0.08);
