/* Contracte landing: a dedicated document-control visual system */
.contracte-page {
  --contracts-ink: #06101d;
  --contracts-mint: #5eead4;
  --contracts-gold: #fbbf24;
  --contracts-paper: #fffdf7;
  background:
    radial-gradient(circle at 14% 6%, rgba(251, 191, 36, 0.15), transparent 26%),
    radial-gradient(circle at 86% 12%, rgba(45, 212, 191, 0.15), transparent 28%),
    linear-gradient(rgba(251, 191, 36, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 234, 212, 0.04) 1px, transparent 1px),
    #06101d;
  background-size: auto, auto, 72px 72px, 72px 72px, auto;
}

.contracte-hero {
  isolation: isolate;
  overflow: hidden;
  border-bottom: 1px solid rgba(251, 191, 36, 0.14);
  background:
    radial-gradient(circle at 74% 26%, rgba(251, 191, 36, 0.19), transparent 17%),
    radial-gradient(circle at 94% 76%, rgba(45, 212, 191, 0.14), transparent 23%),
    linear-gradient(108deg, rgba(45, 212, 191, 0.17), transparent 34%),
    linear-gradient(180deg, #07111f 0%, #081a27 48%, #101d1b 100%);
}

.contracte-hero::after {
  position: absolute;
  z-index: -1;
  right: -10rem;
  bottom: -15rem;
