  height: min(64vw, 64rem);
  border: 1px solid rgba(251, 191, 36, 0.2);
  border-radius: 50%;
  box-shadow:
    0 0 0 5rem rgba(251, 191, 36, 0.025),
    0 0 0 10rem rgba(94, 234, 212, 0.018);
  content: "";
}

.contracte-hero::before {
  right: -4%;
  top: 9%;
  width: 65%;
  height: 74%;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 2rem;
  background:
    linear-gradient(135deg, rgba(251, 191, 36, 0.2), transparent 57%),
