.property-eyebrow {
  display: inline-flex;
  min-height: 2.15rem;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid rgba(15, 118, 110, 0.16);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
  padding: 0 0.82rem;
  color: #0f766e;
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.055em;
  text-transform: uppercase;
  box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
}

.property-eyebrow--dark {
  border-color: rgba(94, 234, 212, 0.2);
  background: rgba(94, 234, 212, 0.075);
  color: #a7f3d0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.property-screen {
  border-color: rgba(148, 163, 184, 0.22);
  background: rgba(255, 255, 255, 0.96);
  box-shadow:
    0 38px 120px rgba(2, 8, 23, 0.44),
    0 0 0 1px rgba(255, 255, 255, 0.12) inset;
}

/* Hero */
.property-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-bottom: 1px solid rgba(94, 234, 212, 0.13);
  background:
    radial-gradient(circle at 88% 10%, rgba(45, 212, 191, 0.18), transparent 28%),
    radial-gradient(circle at 22% 110%, rgba(14, 165, 233, 0.13), transparent 32%),
    linear-gradient(132deg, #07111f 0%, #081827 48%, #062b2b 100%);
}

.property-hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  background: linear-gradient(112deg, transparent 0 54%, rgba(110, 231, 183, 0.07) 54.1% 70%, transparent 70.1%);
  pointer-events: none;
}

.property-hero__grid {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.055) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: linear-gradient(180deg, #000, transparent 94%);
  pointer-events: none;
}

.property-hero__orb {
  position: absolute;
  z-index: 0;
  border-radius: 999px;
  filter: blur(4px);
  pointer-events: none;
}

.property-hero__orb--one {
  right: 8%;
  top: 9%;
  width: 20rem;
  height: 20rem;
  border: 1px solid rgba(103, 232, 249, 0.17);
  box-shadow: 0 0 120px rgba(45, 212, 191, 0.12) inset;
}

.property-hero__orb--two {
  right: 30%;
  bottom: -11rem;
  width: 28rem;
  height: 28rem;
  border: 1px solid rgba(110, 231, 183, 0.1);
}

.property-hero__inner {
  position: relative;
  z-index: 2;
  min-height: 660px;
  padding-top: 3.25rem;
  padding-bottom: 3.4rem;
}

.property-hero__copy {
  position: relative;
  z-index: 4;
  min-width: 0;
}

.property-hero__copy h1 {
  max-width: 39rem;
  margin-top: 1.25rem;
  color: #ffffff;
  font-size: clamp(4rem, 5.1vw, 5.4rem);
  font-weight: 900;
  line-height: 0.92;
}

.property-hero__copy h1 span {
  display: block;
  background: linear-gradient(92deg, #ffffff 4%, #a7f3d0 54%, #67e8f9 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.property-hero__lead {
  max-width: 38rem;
  margin-top: 1.35rem;
  color: rgba(226, 232, 240, 0.82);
  font-size: 1.08rem;
  line-height: 1.68;
}

.property-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.72rem;
  margin-top: 1.65rem;
}

.property-hero__primary {
  height: 3.5rem !important;
  padding-right: 1.55rem !important;
  padding-left: 1.55rem !important;
}

.property-hero__secondary {
  height: 3.5rem !important;
  border-color: rgba(255, 255, 255, 0.16) !important;
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.055) !important;
  padding-right: 1.45rem !important;
  padding-left: 1.45rem !important;
  color: #f8fafc !important;
  font-weight: 800 !important;
  backdrop-filter: blur(14px);
}

.property-hero__secondary:hover {
  background: rgba(255, 255, 255, 0.1) !important;
}

.property-hero__context {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  margin-top: 1.3rem;
}

.property-hero__context span {
  display: inline-flex;
  align-items: center;
  gap: 0.32rem;
  color: rgba(203, 213, 225, 0.75);
  font-size: 0.76rem;
  font-weight: 800;
}

.property-hero__context svg {
  color: #6ee7b7;
}

.property-hero__stage {
  position: relative;
  min-width: 0;
  min-height: 540px;
  perspective: 1200px;
}

.property-hero__stage-glow {
  position: absolute;
  inset: 14% 8% 16%;
  z-index: 0;
  border-radius: 50%;
  background: rgba(45, 212, 191, 0.24);
  filter: blur(90px);
}

.property-hero__stage-label {
  position: absolute;
  left: 1.35rem;
  right: 1.35rem;
  top: 0;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: rgba(203, 213, 225, 0.64);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.property-hero__stage-label span {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.property-hero__stage-label span:first-child {
  color: #a7f3d0;
}

.property-hero__screen {
  position: absolute;
  left: 0;
  right: 0;
  top: 2.35rem;
  z-index: 2;
  width: 100%;
  transform: rotateX(1.4deg) rotateY(-2.2deg);
  transform-origin: center;
  animation: property-screen-float 8s ease-in-out infinite;
}

.property-hero__screen .lux-screen__viewport {
  max-height: 400px;
}

.property-hero__screen .lux-screen__image {
  width: 980px;
}

.property-hero__signals {
  position: absolute;
  right: 0.75rem;
  bottom: 0;
  left: 0.75rem;
  z-index: 5;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.58rem;
}

.property-hero__signal {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 0.62rem;
  border: 1px solid rgba(94, 234, 212, 0.2);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.11), rgba(255, 255, 255, 0.035)),
    rgba(4, 25, 38, 0.88);
  padding: 0.68rem 0.72rem;
  box-shadow:
    0 20px 54px rgba(2, 8, 23, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.09);
  backdrop-filter: blur(18px);
}

.property-hero__signal-icon {
  display: grid;
  width: 2.15rem;
  height: 2.15rem;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 10px;
  background: rgba(94, 234, 212, 0.12);
  color: #67e8f9;
}

.property-hero__signal > span:last-child {
  min-width: 0;
}

.property-hero__signal strong,
.property-hero__signal small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.property-hero__signal strong {
  color: #ffffff;
  font-size: 0.84rem;
  line-height: 1.15;
}

.property-hero__signal small {
  margin-top: 0.18rem;
  color: rgba(203, 213, 225, 0.63);
  font-size: 0.65rem;
  font-weight: 750;
}

/* Shared section typography */
.property-section-head {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(330px, 0.62fr);
  gap: 4rem;
  align-items: end;
}

.property-section-head h2,
.property-workflow__head h2,
.property-roles__head h2,
.property-faq__intro h2,
.property-final h2 {
  color: var(--property-ink);
  font-size: clamp(2.75rem, 4vw, 4.2rem);
  font-weight: 900;
  line-height: 0.98;
}

.property-section-head h2 {
  max-width: 53rem;
  margin-top: 1rem;
}

.property-section-head > p,
.property-workflow__head > p,
.property-faq__intro > p {
  color: rgba(51, 65, 85, 0.78);
  font-size: 1rem;
  line-height: 1.7;
}

/* Capability bento */
.property-overview {
  position: relative;
  color: var(--property-ink);
  background:
    radial-gradient(circle at 12% 0%, rgba(45, 212, 191, 0.14), transparent 30%),
    linear-gradient(180deg, #fbfdfc 0%, #eef6f4 100%);
}

.property-capability-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 0.85rem;
  margin-top: 2.5rem;
}

.property-capability-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  grid-column: span 4;
  min-height: 15.8rem;
  border: 1px solid rgba(15, 118, 110, 0.13);
  border-radius: 22px;
  background:
    radial-gradient(circle at 100% 0%, rgba(45, 212, 191, 0.13), transparent 35%),
    rgba(255, 255, 255, 0.84);
  padding: 1.35rem;
  box-shadow:
    0 24px 60px rgba(15, 23, 42, 0.075),
    inset 0 1px 0 rgba(255, 255, 255, 0.96);
  transition:
    transform 220ms ease,
    border-color 220ms ease,
    box-shadow 220ms ease;
}

.property-capability-card::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(135deg, rgba(103, 232, 249, 0.08), transparent 42%);
  opacity: 0;
  transition: opacity 220ms ease;
}

.property-capability-card:hover {
  border-color: rgba(15, 118, 110, 0.26);
  box-shadow: 0 32px 75px rgba(15, 23, 42, 0.11);
  transform: translateY(-4px);
}

.property-capability-card:hover::before {
  opacity: 1;
}

.property-capability-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.property-capability-card__icon {
  display: grid;
  width: 2.65rem;
  height: 2.65rem;
  place-items: center;
  border: 1px solid rgba(13, 148, 136, 0.14);
  border-radius: 13px;
  background: #e8faf5;
  color: #0f766e;
}

.property-capability-card__meta {
  color: rgba(15, 118, 110, 0.58);
  font-size: 0.65rem;
  font-weight: 950;
  letter-spacing: 0.09em;
}

.property-capability-card h3 {
  max-width: 21rem;
  margin-top: 3.35rem;
  color: #07111f;
  font-size: 1.38rem;
  font-weight: 900;
  line-height: 1.08;
}

.property-capability-card p {
  max-width: 23rem;
  margin-top: 0.7rem;
  color: rgba(51, 65, 85, 0.75);
  font-size: 0.91rem;
  line-height: 1.55;
}

.property-capability-card__arrow {
  position: absolute;
  right: 1.2rem;
  bottom: 1.15rem;
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 999px;
  background: #07111f;
  color: #ffffff;
}

.property-capability-card--1,
.property-capability-card--6 {
  background:
    radial-gradient(circle at 90% 10%, rgba(103, 232, 249, 0.14), transparent 35%),
    linear-gradient(145deg, #ffffff 0%, #eaf8f4 100%);
}

/* Compact portfolio command center */
.property-priority {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  color: #ffffff;
  background:
    linear-gradient(rgba(94, 234, 212, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(94, 234, 212, 0.03) 1px, transparent 1px),
    linear-gradient(128deg, #06101d 0%, #081927 48%, #06302e 100%);
  background-size: 64px 64px, 64px 64px, auto;
}

.property-priority__glow {
  position: absolute;
  right: 3%;
  top: -22rem;
  width: 42rem;
  height: 42rem;
  border-radius: 999px;
  background: rgba(45, 212, 191, 0.15);
  filter: blur(90px);
  pointer-events: none;
}

.property-priority > div:last-child {
  position: relative;
  z-index: 2;
}

.property-priority__head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.66fr);
  gap: 3rem;
  align-items: end;
}

.property-priority__head h2 {
  max-width: 42rem;
  margin-top: 0.85rem;
  color: #ffffff;
  font-size: clamp(2.8rem, 3.5vw, 3.75rem);
  font-weight: 900;
  line-height: 0.96;
}

.property-priority__head > p {
  max-width: 37rem;
  color: rgba(203, 213, 225, 0.77);
  font-size: 0.98rem;
  line-height: 1.66;
}

.property-priority__cockpit {
  display: grid;
  grid-template-columns: minmax(0, 1.44fr) minmax(330px, 0.56fr);
  gap: 0.85rem;
  margin-top: 1.75rem;
}

.property-priority__media,
.property-priority__signals {
  overflow: hidden;
  border: 1px solid rgba(94, 234, 212, 0.17);
  border-radius: 20px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.025)),
    rgba(2, 12, 23, 0.54);
  box-shadow:
    0 28px 85px rgba(0, 0, 0, 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
}

.property-priority__media {
  min-width: 0;
  padding: 0.65rem;
}

.property-priority__media-toolbar {
  display: flex;
  min-height: 2.15rem;
  align-items: center;
  justify-content: space-between;
  padding: 0 0.35rem 0.55rem;
  color: rgba(203, 213, 225, 0.67);
  font-size: 0.68rem;
  font-weight: 800;
}

.property-priority__media-toolbar span {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
}

.property-priority__media-toolbar span:last-child {
  color: #a7f3d0;
}

.property-priority__screen {
  border-radius: 14px;
  transform: none;
}

.property-priority__screen .lux-screen__bar {
  min-height: 2.55rem;
}

.property-priority__screen .lux-screen__viewport {
  max-height: 310px;
}

.property-priority__screen .lux-screen__image {
  width: 900px;
}

.property-priority__signals {
  padding: 0.72rem;
}

.property-priority__signals-head {
  display: flex;
  min-height: 3.65rem;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  border-bottom: 1px solid rgba(148, 163, 184, 0.13);
  padding: 0 0.35rem 0.7rem;
}

.property-priority__signals-head div span,
.property-priority__signals-head div strong {
  display: block;
}

.property-priority__signals-head div span {
  color: #67e8f9;
  font-size: 0.61rem;
  font-weight: 950;
  letter-spacing: 0.09em;
}

.property-priority__signals-head div strong {
  margin-top: 0.22rem;
  color: #ffffff;
  font-size: 0.93rem;
}

.property-priority__live {
  display: inline-flex;
  min-height: 1.7rem;
  align-items: center;
  gap: 0.3rem;
  border: 1px solid rgba(110, 231, 183, 0.18);
  border-radius: 999px;
  background: rgba(110, 231, 183, 0.08);
  padding: 0 0.55rem;
  color: #a7f3d0;
  font-size: 0.6rem;
  font-weight: 950;
}

.property-priority__signal-list {
  display: grid;
  gap: 0.42rem;
  margin-top: 0.55rem;
}

.property-priority__signal-list article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
  min-height: 3.7rem;
  border: 1px solid rgba(148, 163, 184, 0.11);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.035);
  padding: 0.58rem 0.62rem;
}

.property-priority__signal-list article > span {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border-radius: 10px;
  background: rgba(94, 234, 212, 0.09);
  color: #67e8f9;
}

.property-priority__signal-list article > svg {
  color: rgba(203, 213, 225, 0.42);
}

.property-priority__signal-list h3 {
  color: #f8fafc;
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: -0.01em;
}

.property-priority__signal-list p {
  margin-top: 0.16rem;
  color: rgba(203, 213, 225, 0.57);
  font-size: 0.64rem;
  line-height: 1.35;
}

/* Workflow */
.property-workflow {
  color: var(--property-ink);
  background:
    radial-gradient(circle at 90% 0%, rgba(103, 232, 249, 0.11), transparent 26%),
    linear-gradient(180deg, #f8fcfb 0%, #edf6f3 100%);
}

.property-workflow__head {
  display: grid;
  max-width: 58rem;
  justify-items: center;
  margin: 0 auto;
  text-align: center;
}

.property-workflow__head h2 {
  margin-top: 1rem;
}

.property-workflow__head > p {
  max-width: 42rem;
  margin-top: 1rem;
}

.property-workflow__track {
  position: relative;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.75rem;
  margin-top: 2.75rem;
}

.property-workflow__track::before {
  content: "";
  position: absolute;
  left: 9%;
  right: 9%;
  top: 3.45rem;
  z-index: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(13, 148, 136, 0.36) 10%, rgba(13, 148, 136, 0.36) 90%, transparent);
}

.property-workflow__step {
  position: relative;
  z-index: 1;
  min-height: 13.5rem;
  border: 1px solid rgba(15, 118, 110, 0.13);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.78);
  padding: 1rem;
  box-shadow: 0 20px 52px rgba(15, 23, 42, 0.06);
}

.property-workflow__number {
  position: absolute;
  right: 0.85rem;
  top: 0.7rem;
  color: rgba(15, 118, 110, 0.15);
  font-family: var(--font-space-grotesk);
  font-size: 2.8rem;
  font-weight: 900;
  line-height: 1;
}

.property-workflow__icon {
  display: grid;
  width: 3.05rem;
  height: 3.05rem;
  place-items: center;
  border: 6px solid #f5faf8;
  border-radius: 999px;
  background: #0f766e;
  color: #ffffff;
  box-shadow: 0 0 0 1px rgba(15, 118, 110, 0.14);
}

.property-workflow__step h3 {
  margin-top: 2.8rem;
  color: #07111f;
  font-size: 1.13rem;
  font-weight: 900;
}

.property-workflow__step p {
  margin-top: 0.55rem;
  color: rgba(51, 65, 85, 0.72);
  font-size: 0.83rem;
  line-height: 1.52;
}

.property-workflow__result {
  display: flex;
  max-width: 54rem;
  min-height: 3.6rem;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  margin: 1.2rem auto 0;
  border: 1px solid rgba(15, 118, 110, 0.15);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.68);
  padding: 0.7rem 1.2rem;
  color: rgba(51, 65, 85, 0.75);
  font-size: 0.82rem;
}

.property-workflow__result svg,
.property-workflow__result strong {
  color: #0f766e;
}

/* Roles */
.property-roles {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(circle at 8% 0%, rgba(45, 212, 191, 0.16), transparent 30%),
    radial-gradient(circle at 92% 100%, rgba(14, 165, 233, 0.12), transparent 30%),
    #07111f;
}

.property-roles__head {
  display: grid;
  max-width: 69rem;
  gap: 1rem;
}

.property-roles__head h2 {
  color: #ffffff;
}

.property-roles__grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
  margin-top: 2.2rem;
}

.property-role-card {
  position: relative;
  overflow: hidden;
  min-height: 22rem;
  border: 1px solid rgba(94, 234, 212, 0.16);
  border-radius: 24px;
  background:
    linear-gradient(145deg, rgba(94, 234, 212, 0.1), transparent 42%),
    rgba(255, 255, 255, 0.045);
  padding: 1.6rem;
  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
}

.property-role-card--2 {
  background:
    linear-gradient(145deg, rgba(103, 232, 249, 0.1), transparent 42%),
    rgba(255, 255, 255, 0.045);
}

.property-role-card__icon {
  display: grid;
  width: 3.2rem;
  height: 3.2rem;
  place-items: center;
  border: 1px solid rgba(94, 234, 212, 0.17);
  border-radius: 15px;
  background: rgba(94, 234, 212, 0.09);
  color: #67e8f9;
}

.property-role-card__overline {
  display: block;
  margin-top: 2.2rem;
  color: #6ee7b7;
  font-size: 0.66rem;
  font-weight: 950;
  letter-spacing: 0.1em;
}

.property-role-card h3 {
  max-width: 34rem;
  margin-top: 0.55rem;
  color: #ffffff;
  font-size: clamp(1.75rem, 2.5vw, 2.65rem);
  font-weight: 900;
  line-height: 1;
}

.property-role-card > p {
  max-width: 38rem;
  margin-top: 0.9rem;
  color: rgba(203, 213, 225, 0.73);
  font-size: 0.94rem;
  line-height: 1.6;
}

.property-role-card ul {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 1.25rem;
}

.property-role-card li {
  display: inline-flex;
  align-items: center;
  gap: 0.38rem;
  border: 1px solid rgba(148, 163, 184, 0.13);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.04);
