/* Anatomy: every commercial detail around one living property record */
.property-anatomy {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  color: #ffffff;
  background:
    radial-gradient(circle at 50% 48%, rgba(45, 212, 191, 0.17), transparent 30%),
    radial-gradient(circle at 8% 10%, rgba(14, 165, 233, 0.11), transparent 27%),
    linear-gradient(135deg, #040b15 0%, #071725 50%, #052c2b 100%);
}

.property-anatomy::before,
.property-anatomy::after {
  content: "";
  position: absolute;
  z-index: 0;
  border: 1px solid rgba(103, 232, 249, 0.08);
  pointer-events: none;
}

.property-anatomy::before {
  right: -12%;
  top: 8%;
  width: 55%;
  height: 68%;
  transform: skewX(-12deg) rotate(-3deg);
}

.property-anatomy::after {
  left: -16%;
  bottom: -28%;
  width: 48%;
  height: 55%;
  border-radius: 999px;
}

.property-anatomy__grid {
  position: absolute;
  inset: 0;
  z-index: 0;
  background-image:
    linear-gradient(rgba(94, 234, 212, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(103, 232, 249, 0.03) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(circle at center, #000, transparent 88%);
}

.property-anatomy > div:last-child {
  position: relative;
  z-index: 2;
}

.property-anatomy__head {
  display: grid;
  max-width: 64rem;
  justify-items: center;
  margin: 0 auto;
  text-align: center;
}

.property-anatomy__head h2 {
  max-width: 58rem;
  margin-top: 1rem;
  background: linear-gradient(92deg, #ffffff 0%, #d1fae5 55%, #a5f3fc 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-family: var(--font-space-grotesk);
  font-size: clamp(3.05rem, 4.6vw, 4.65rem);
  font-weight: 900;
  line-height: 0.96;
  letter-spacing: -0.04em;
}

.property-anatomy__head p {
  max-width: 48rem;
  margin-top: 1rem;
  color: rgba(203, 213, 225, 0.72);
  font-size: 1rem;
  line-height: 1.7;
}

.property-anatomy__stage {
  display: grid;
  grid-template-columns: minmax(260px, 0.72fr) minmax(500px, 1.28fr) minmax(260px, 0.72fr);
  gap: 0.8rem;
  align-items: center;
  margin-top: 3rem;
}

.property-anatomy__column {
  position: relative;
  z-index: 3;
  display: grid;
  gap: 0.58rem;
}

.property-anatomy__item {
  position: relative;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  gap: 0.65rem;
  align-items: center;
  min-height: 6.3rem;
  border: 1px solid rgba(148, 163, 184, 0.13);
